        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 53,
        marker = "**",
        depth = 2,
        instruction = "It is advised not to completely trust auto-follow (Command/follow) in this situation, moving along the Tor manually. This way, if one of your leading members makes a mistake and falls off the Tor (which can be more often than one would think), you will maintain your position on the path.",
