        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 54,
        marker = "*",
        depth = 1,
        instruction = "Along the way you will encounter vents of miasma that block your path, similar to the vents in the area surrounding the Tor itself. Unlike those, however, there are some on the Tor that stop venting for a moment, allowing you (very brief) access.",
        action = "note",
        entities = {  },
