      },
      {
        order = 42,
        marker = "**",
        depth = 2,
        instruction = "Lioumere will \"lose\" all hate and return to its Spawn Point after it uses a weapon skill. If the Lioumere is allowed to return to its Spawn Point he will recover all HP. The antlion is susceptible to Bind, Gravity, Desperate Flourish, and Sleep. If the Lioumere is hit a couple times before he returns to his Spawn Point, hate will be regained and he will stop.",
        action = "note",
        entities = { "Lioumere", "Spawn Point", "Bind", "Gravity", "Desperate Flourish", "Sleep" },
        zones = {  },
