        depth = 2,
        instruction = "He may mention Aht Urhgan depending on your progress through that story. Speak to him again to trigger the cutscene.",
        action = "talk",
        entities = { "Aht Urhgan" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
