      {
        order = 3,
        marker = "**",
        depth = 2,
        instruction = "If you are on Rhapsodies of Vana'diel mission Crashing Waves, you will receive the message: \"You are unable to make further progress in Rhapsodies of Vana'diel due to an event occuring in the Chains of Promathia missions\" upon entering the Archduke Grand Palace.",
        action = "note",
        entities = { "Rhapsodies of Vana'diel", "Crashing Waves" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 4,
        marker = "*",
        depth = 1,
        instruction = "(Optional) Speak to Rainhard by the double doors upstairs in the Palace for a comment about the \"poor soul\" waiting in the Archduke's House.",
