  ["mission:Chains of Promathia:31"] = {
    objective_name = "The Enduring Tumult of War",
    page = {
      title = "The Enduring Tumult of War",
      page_id = 13602,
      revision_id = 1800564,
      revision_timestamp = "2026-07-22T06:04:07Z",
