    steps = {
      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "If you're not on or past Both Paths Taken of Rhapsodies of Vana'diel, it's strongly recommended you finish that before continuing. You will not be able to progress in that mission line until you flag Three Paths.",
