      },
      {
        order = 2,
        marker = "*",
        depth = 1,
        instruction = "Optional: Head to the top floor of the Tavnazian Safehold and go behind the Walnut Door at (Tavnazian Safehold Map 2 K-10) / (Tavnazian Safehold Map 2 J-9) border and talk to Despachiaire for a cutscene.",
        action = "note",
