        marker = "*",
        depth = 1,
        instruction = "Optional: Go to Northern San d'Oria L-6 and talk to Chasalvige (Cathedral - Manuscript Room). He will have no information on events you describe and suggest to ask around at Port San d'Oria.",
        action = "note",
        entities = { "Chasalvige" },
