        warnings = {  },
      },
      {
        order = 5,
        marker = "*",
        depth = 1,
        instruction = "Optional: Go to Port San d'Oria H-6 and talk to Anoki for a cutscene where he will have hard time believing you. Talk with him again for dialog where he suggests you ask around at the other agencies as long as you do not mind your sanity being questioned.",
