  ["mission:Chains of Promathia:32"] = {
    objective_name = "Desires of Emptiness",
    page = {
      title = "Desires of Emptiness",
      page_id = 13603,
      revision_id = 1795083,
      revision_timestamp = "2026-05-11T00:59:41Z",
      content_sha256 = "e42942b07df4cdff916674dcb525e55b20a596ac08a027a002c03ce0e36efead",
      source_url = "https://ffxiclopedia.fandom.com/wiki/Desires_of_Emptiness",
      license = "CC-BY-SA-3.0",
    },
    steps = {
      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "Note: The information here is from when there was a Level Restriction at 50. Any job at 75+, and even considerably lower, can solo this mission with varying difficulty/speed. As with other Promyvion areas, there are aggressive monsters around level 80, but they are easily identified from their names and can be avoided as long as players pay attention to them. Note - It is... Required details: Level Restriction.",
        action = "note",
        entities = { "Level Restriction" },
        zones = { "Spire of Vahzl" },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = { "unknown-template:testimonials" },
      },
      {
        order = 2,
        marker = "*",
        depth = 1,
        instruction = "Section: Promyvion-Vahzl.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 3,
        marker = "*",
        depth = 1,
        instruction = "Promyvion - Vahzl is five islands instead of four, and the monsters are stronger than in other areas of Promyvion. Like the other Promyvions, it's only tough if you or your party is aggroing everything in sight. At level 75, although many monsters will check as Easy Prey, nothing will be a high-enough level to aggro.",
        action = "note",
        entities = { "Promyvion - Vahzl", "Promyvion", "Easy Prey" },
        zones = { "Promyvion - Vahzl" },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 4,
        marker = "*",
        depth = 1,
        instruction = "Idle Wanderers, Woeful Weepers, and Livid Seethers are aggressive to 99, and deadly to level 75, so be careful around them. It should not be necessary to go near them for the mission.",
        action = "note",
        entities = { "Idle Wanderer", "Woeful Weeper", "Livid Seether" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 5,
        marker = "*",
        depth = 1,
        instruction = "If you see any Apex monsters here, avoid them at all costs, even at level 99 they will likely be deadly to you.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 6,
        marker = "*",
        depth = 1,
        instruction = "*On the third, fourth, and fifth islands, you will have to rescue your companions from prisons before moving to the next floor. Search for Memory Flux gates before proceeding to the Memory Receptacles so that you do not leave the floor before freeing your companions. Each Memory Flux Gate will spawn a Notorious Monster. these are mandatory fights... Required details: Memory Flux, Memory Receptacles, Spire of Vahzl.",
        action = "note",
        entities = { "Memory Flux", "Memory Receptacle", "Spire of Vahzl" },
        zones = { "Spire of Vahzl" },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 7,
        marker = "*",
        depth = 1,
        instruction = "TLDR: Green Gate on the Promvyion Vahzl Map for floor 3/4/5 spawns NM. Kill it and examine the gate again afterwords before moving to the next floor. Do this on all three floors.",
        action = "examine",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 8,
        marker = "*",
        depth = 1,
        instruction = "Make sure to examine the Memory Flux after defeating each NM.",
        action = "examine",
        entities = { "Memory Flux" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 9,
        marker = "**",
        depth = 2,
        instruction = "Third island: Propagator (Gorger type) will spawn multiple Offspring if given the chance; be prepared to deal with these adds. They will all die if the Propagator is killed.",
        action = "note",
        entities = { "Propagator", "Offspring" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 10,
        marker = "**",
        depth = 2,
        instruction = "Fourth island: Solicitor (Craver type) has a dangerous single-target attack and an AoE Poison attack that deals damage and gives a strong poison effect. It is advisable that jobs that cannot cure poison have a few antidotes. Also, if needed, have someone cast Gravity on the NM so healers can Cure without worrying about any threats.",
        action = "note",
        entities = { "Solicitor", "Gravity" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 11,
        marker = "**",
        depth = 2,
