        warnings = {  },
      },
      {
        order = 33,
        marker = "*",
        depth = 1,
        instruction = "2. Trade a Snow Lily to Tarnotik in Oldton Movalpolos at (Oldton Movalpolos K-10), and you will be warped to the Mine Shaft #2716.",
