        entities = { "Twinkbrix" },
        zones = { "Oldton Movalpolos" },
        map_numbers = {  },
        grid_coordinates = { "E-13" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 39,
        marker = "***",
        depth = 3,
        instruction = "Give Twinkbrix an amount between 1-10,000 gil, to have a chance at getting the Key Item Shaft Gate Operating Dial, which is required for the two ENM60 battles here. He will roll a number 2 through 100. Your chances of winning is based on how much money you give him. 10,000 gil will only give you a 50% chance of winning.",
