      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "Head to any of the Shattered Telepoints at Crag of Mea, Crag of Dem, Crag of Holla to enter Promyvion.",
        action = "travel",
        entities = { "Shattered Telepoint", "Crag of Mea", "Crag of Dem", "Crag of Holla", "Promyvion" },
        zones = {  },
