        warnings = {  },
      },
      {
        order = 2,
        marker = "**",
        depth = 2,
        instruction = "If you have entered one of the 3 areas before and then go to another without clearing the one you previously enter, you have to seal your memories of the previous one, which you will be prompted to do when checking the Shattered Telepoint at a different Crag.",
        action = "note",
        entities = { "Shattered Telepoint" },
        zones = {  },
