      license = "CC-BY-SA-3.0",
    },
    steps = {
      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "If you're not on or past Both Paths Taken of Rhapsodies of Vana'diel, it's strongly recommended you finish that before continuing. Once you start The Warrior's Path, you will not be able to progress in those missions until the final cutscene of Dawn, which includes a Japanese Midnight wait.",
