        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 2,
        marker = "*",
        depth = 1,
        instruction = "You will now have to kill three NMs. They can be done in any order and are all uncapped. They're all fairly simple at level 75+ with Trust, trivial at Item Level.",
