      source_url = "https://ffxiclopedia.fandom.com/wiki/The_Warrior's_Path",
      license = "CC-BY-SA-3.0",
    },
    steps = {
      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "Head to Sealion's Den and click on the \"Iron Gate\" for a Cutscene. After the Cutscene you can click the \"Iron Gate\" once more for the airship fight, \"The Warrior's Path\".",
        action = "examine",
        entities = { "Sealion's Den" },
        zones = { "Sealion's Den" },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 2,
        marker = "*",
        depth = 1,
        instruction = "Originally uncapped, then capped at 75 in the March 2007 update, and now, uncapped again, but still with the Level Restriction effect (TP and all buffs are removed upon entering the battlefield. Food effects are not removed.) Soloable at level 75+ with Alter Egos. Easy at Item Level.",
        action = "note",
        entities = { "Level Restriction", "Alter Egos", "Item Level" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
