        warnings = {  },
      },
      {
        order = 27,
        marker = "*",
        depth = 1,
        instruction = "Tenzen will use Meikyo Shisui at some point, and then begin to to self-Skillchain whoever has hate. After an initial 3 WS, Tenzen may or may not use Amatsu: Tsukikage, an unavoidable ranged Great Katana WS that bypasses shadows, triggering the Cosmic Elucidation Skillchain which deals over 1000 damage to all players in range and triggers ejection from the BC, much like the Snoll Tzar encounter.",
        action = "note",
        entities = { "Tenzen", "Meikyo Shisui", "Skillchain", "Cosmic Elucidation", "Snoll Tzar" },
        zones = {  },
        map_numbers = {  },
